import json,os,pathlib
wanted={'freecad','FreeCAD','Xorg','Xvfb','gnome-shell','gdm3','gdm-session-wor','openbox','snap-exec','snap-confine'}
procs=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit(): continue
 try:
  comm=(p/'comm').read_text().strip()
  if comm in wanted or 'freecad' in comm.lower():
   status=(p/'status').read_text().splitlines(); procs.append({'pid':p.name,'comm':comm,'state':next((s for s in status if s.startswith('State:')),None)})
 except (FileNotFoundError,PermissionError,ProcessLookupError): pass
root=pathlib.Path('/home/user/actc_infra_boot_001')
print(json.dumps({'display_environment':{k:os.environ.get(k) for k in ['DISPLAY','WAYLAND_DISPLAY','XDG_SESSION_TYPE','XDG_RUNTIME_DIR','QT_QPA_PLATFORM']},'x11_sockets':[p.name for p in pathlib.Path('/tmp/.X11-unix').glob('*')],'processes':procs,'own_files':[p.name for p in root.glob('*')]}))
